local LANG = {
	deDE = "de", frFR = "fr", esES = "es", esMX = "es", itIT = "it", ptBR = "pt",
	ruRU = "ru", koKR = "ko", zhCN = "zh", zhTW = "tw",
}
-- the lines of one update in the language of your game client (English otherwise)
function ns:PatchLines(entry)
	local key = LANG[GetLocale and GetLocale() or "enUS"] or "en"
	return entry[key] or entry.en
end
